    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves a brick collision for the ball: flips the right velocity
// component(s), pushes the ball back out of the brick, and returns the brick
// that was hit (or null). The bounce is applied AT MOST ONCE per call, so a
// ball straddling the seam between two bricks does not get its velocity
// flipped twice (which would cancel out and let it plow through).
// `prevX`/`prevY` are the ball's position before the current move: the segment
// between the two positions is swept to catch tunnelling (see ISSUES.md #1).
export function brickHit(ball, bricks, prevX = ball.prevX ?? ball.x, prevY = ball.prevY ?? ball.y) {
  // TODO(#1): real per-face bounce + push-out + sweep. Stub: never hits.
  return null;
}

