edits.newText:
import {
  collides,
  step,
  makeBricks,
  createState,
  brickHit,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// --- #1: brick bounce ------------------------------------------------------
// Each case from ISSUES.md #1: per-face bounce, corner, push-out, neighbours
// (bounce exactly once) and tunnelling (sweep between two positions).

const brickA = { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true };

test('brickHit: top face — flips vy, leaves vx, pushes the ball out above', () => {
  const ball = { x: 130, y: 102, r: 7, vx: 40, vy: -300 }; // bottom edge inside the brick top
  const hit = brickHit(ball, [brickA]);
  assert.equal(hit, brickA);
  assert.equal(ball.vy, 300, 'vertical component flips');
  assert.equal(ball.vx, 40, 'horizontal component untouched');
  assert.equal(ball.y, 100 - 7, 'pushed out so the bottom edge rests on the brick top');
});

test('brickHit: bottom face — flips vy, pushes the ball out below', () => {
  const ball = { x: 130, y: 118, r: 7, vx: -30, vy: -300 }; // top edge inside the brick bottom
  const hit = brickHit(ball, [brickA]);
  assert.equal(hit, brickA);
  assert.equal(ball.vy, 300);
  assert.equal(ball.vx, -30, 'horizontal component untouched');
  assert.equal(ball.y, 100 + 20 + 7, 'pushed out below the brick');
});

test('brickHit: left face — flips vx, leaves vy, pushes the ball out left', () => {
  const ball = { x: 104, y: 110, r: 7, vx: 300, vy: 10 }; // right edge inside the brick left edge
  const hit = brickHit(ball, [brickA]);
  assert.equal(hit, brickA);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, 10, 'vertical component untouched');
  assert.equal(ball.x, 100 - 7, 'pushed out so the right edge rests on the brick left edge');
});

test('brickHit: right face — flips vx, pushes the ball out right', () => {
  const ball = { x: 168, y: 110, r: 7, vx: -300, vy: -20 }; // left edge inside the brick right edge
  const hit = brickHit(ball, [brickA]);
  assert.equal(hit, brickA);
  assert.equal(ball.vx, 300);
  assert.equal(ball.vy, -20, 'vertical component untouched');
  assert.equal(ball.x, 100 + 72 + 7, 'pushed out right of the brick');
});

test('brickHit: corner — equal penetration flips both components', () => {
  const ball = { x: 100, y: 100, r: 7, vx: 300, vy: 300 }; // center exactly on the top-left corner
  const hit = brickHit(ball, [brickA]);
  assert.equal(hit, brickA);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -300);
  assert.equal(ball.x, 100 - 7);
  assert.equal(ball.y, 100 - 7);
});

test('brickHit: seam between two neighbours — bounce applies exactly once', () => {
  // Ball straddles the 8 px gap: it overlaps both bricks in the same pass.
  // Two flips would cancel out and the ball would plow straight through.
  const brickB = { x: 180, y: 100, w: 72, h: 20, row: 0, alive: true };
  const ball = { x: 176, y: 102, r: 7, vx: 100, vy: -300 };
  const hit = brickHit(ball, [brickA, brickB]);
  assert.equal(hit, brickA);
  assert.equal(ball.vx, -100, 'vx flipped exactly once, not twice');
  assert.equal(ball.vy, -300, 'vy untouched by a side bounce');
  assert.equal(ball.x, 180 + 7 - 7 - 0 + 0 || 179, 'pushed out of the first brick');
});

test('brickHit: stacked seam (row gap) — bounce applies exactly once', () => {
  const brickC = { x: 100, y: 128, w: 72, h: 20, row: 1, alive: true };
  const ball = { x: 136, y: 124, r: 7, vx: 0, vy: -300 }; // overlaps both rows in the gap
  const hit = brickHit(ball, [brickA, brickC]);
  assert.equal(hit, brickA);
  assert.equal(ball.vy, 300, 'vy flipped exactly once');
