edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the per-face bounce is decided in `brickHit` (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce (tested primitive — see ISSUES.md #1) --------------------

// Two penetrations this close count as a diagonal (corner) hit.
const CORNER_EPS = 0.5;
// Two sweep entry times this close count as entering through a corner.
const SWEEP_EPS = 1e-7;

// Resolves a brick collision for the ball: flips the right velocity
// component(s) (vy on a top/bottom hit, vx on a side hit, both on a corner),
// pushes the ball back out of the brick, and returns the brick that was hit
// (or null). The bounce is applied AT MOST ONCE per call, so a ball straddling
// the seam between two bricks does not get its velocity flipped twice (which
// would cancel out and let it plow through).
// `prevX`/`prevY` are the ball's position before the current move: the segment
// between the two positions is swept to catch tunnelling (a level-6 stuttered
// frame moves the ball 35.5 px, more than the 34 px needed to cross a brick).
export function brickHit(ball, bricks, prevX = ball.prevX ?? ball.x, prevY = ball.prevY ?? ball.y) {
  for (const brick of bricks) {
    if (!brick.alive) continue;

    // Discrete overlap at the current position: the face is decided by which
    // axis penetrated less (the smaller overlap is the face that was hit).
    if (collides(ball, brick)) {
      resolveOverlap(ball, brick);
      return brick;
    }

    // No current overlap: the ball may have jumped over the brick in one
    // stuttered step. Sweep the segment it travelled this frame.
    const swept = sweptHit(ball, prevX, prevY, brick);
    if (swept) {
      resolveSwept(ball, brick, swept);
      return brick;
    }
  }
  return null;
}

// Discrete resolution: the ball overlaps the brick right now. The axis with
// the smaller penetration is the face that was hit; equal penetrations mean a
// corner. Always push the ball out along the resolved axis so it cannot stay
// overlapped and re-flip on the next frame (sticky bounce).
function resolveOverlap(ball, brick) {
  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  if (Math.abs(overlapX - overlapY) <= CORNER_EPS) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    pushOut(ball, brick, 'x');
    pushOut(ball, brick, 'y');
  } else if (overlapX < overlapY) {
    ball.vx = -ball.vx;
    pushOut(ball, brick, 'x');
  } else {
    ball.vy = -ball.vy;
    pushOut(ball, brick, 'y');
  }
}

// Swept resolution: the ball crossed the brick between its previous and its
// current position. The face is the slab whose entry time is later (the face
// actually struck); the ball is pushed back out through that same face, i.e.
// toward the side it came from.
function resolveSwept(ball, brick, swept) {
  const { tEnterX, tEnterY, dx, dy } = swept;

  if (tEnterX !== null && tEnterY !== null && Math.abs(tEnterX - tEnterY) <= SWEEP_EPS) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    pushOutFrom(ball, brick, dx, dy, 'x');
    pushOutFrom(ball, brick, dx, dy, 'y');
  } else if (tEnterX !== null && (tEnterY === null || tEnterX > tEnterY)) {
    ball.vx = -ball.vx;
    pushOutFrom(ball, brick, dx, dy, 'x');
  } else {
    ball.vy = -ball.vy;
    pushOutFrom(ball, brick, dx, dy, 'y');
  }
}

// Segment/rect sweep: does the ball (as a point) cross the brick's AABB
// inflated by the ball radius between (prevX, prevY) and (ball.x, ball.y)?
// Returns the entry-face data on a hit, null otherwise. A negative entry time
// means the ball started inside the inflated rect: ambiguous, no sweep hit.
function sweptHit(ball, prevX, prevY, brick) {
  if (prevX === ball.x && prevY === ball.y) return null;

  const r = ball.r;
  const left = brick.x - r;
  const right = brick.x + brick.w + r;
  const top = brick.y - r;
  const bottom = brick.y + brick.h + r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let tEnter = -Infinity;
  let tExit = Infinity;
  let tEnterX = null;
  let tEnterY = null;

  if (dx === 0) {
    if (ball.x <= left || ball.x >= right) return null;
  } else {
    let t1 = (left - prevX) / dx;
    let t2 = (right - prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnterX = t1;
    if (t1 > tEnter) tEnter = t1;
    if (t2 < tExit) tExit = t2;
  }

  if (dy === 0) {
    if (ball.y <= top || ball.y >= bottom) return null;
  } else {
    let t1 = (top - prevY) / dy;
    let t2 = (bottom - prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnterY = t1;
    if (t1 > tEnter) tEnter = t1;
    if (t2 < tExit) tExit = t2;
  }

  if (tEnter > tExit) return null;
  if (tExit < 0) return null; // crossed before this frame started
  if (tEnter > 1) return null; // crosses only after this frame
  if (tEnter < 0) return null; // started inside the inflated rect: ambiguous

  return { tEnterX, tEnterY, dx, dy };
}

// Push the ball out along one axis, toward the nearest edge of the brick
// (used when the ball currently overlaps the brick).
function pushOut(ball, brick, axis) {
  if (axis === 'x') {
    if (ball.x < brick.x + brick.w / 2) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else {
    if (ball.y < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  }
}

// Push the ball out along one axis, toward the face it entered through
// (used for swept hits, where the current position may be past the brick).
function pushOutFrom(ball, brick, dx, dy, axis) {
  if (axis === 'x') {
    if (dx > 0) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else {
    if (dy > 0) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  }
}

